namespace crypto {

class CircuitBreaker {
public:
    enum class State { CLOSED, OPEN, HALF_OPEN };

    CircuitBreaker(int threshold = 5, int timeout_ms = 30000)
        : failure_count_(0), threshold_(threshold),
          timeout_ms_(timeout_ms), state_(State::CLOSED) {}

    bool allow_request() const {
        return state_.load() != State::OPEN;
    }

    void record_success() {
        failure_count_.store(0);
        state_.store(State::CLOSED);
    }

    void record_failure() {
        if (failure_count_.fetch_add(1) + 1 >= threshold_) {
            state_.store(State::OPEN);
        }
    }

private:
    std::atomic<int> failure_count_;
    int threshold_;
    int timeout_ms_;
    std::atomic<State> state_;
};

struct BlockContext {
    alignas(16) uint8_t round_keys[240];
    uint32_t nr;
    uint32_t key_len;
};

static inline uint32_t rotr32(uint32_t val, unsigned int n) {
    return (val >> n) | (val << (32 - n));
}

static inline uint32_t load_le32(const uint8_t* p) {
    return (uint32_t)p[0] | ((uint32_t)p[1] << 8) |
           ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
}

static inline void store_le32(uint8_t* p, uint32_t v) {
    p[0] = (uint8_t)(v);
    p[1] = (uint8_t)(v >> 8);
    p[2] = (uint8_t)(v >> 16);
    p[3] = (uint8_t)(v >> 24);
}

class AESProcessor {
public:
    AESProcessor() : breaker_(3, 5000) {}

    bool init_key(const uint8_t* key, size_t key_len) {
        if (!breaker_.allow_request()) {
            return false;
        }

        if (key_len != 16 && key_len != 24 && key_len != 32) {
            breaker_.record_failure();
            return false;
        }

        ctx_.key_len = static_cast<uint32_t>(key_len);
        ctx_.nr = (ctx_.key_len >> 2) + 6;

        expand_key(key, key_len);
        breaker_.record_success();
        return true;
    }

    bool process_block(const uint8_t* input, uint8_t* output, size_t len) {
        if (!breaker_.allow_request()) {
            return false;
        }

        if (len == 0 || (len % 16) != 0) {
            breaker_.record_failure();
            return false;
        }

        for (size_t offset = 0; offset < len; offset += 16) {
            encrypt_single_block(input + offset, output + offset);
        }

        breaker_.record_success();
        return true;
    }

private:
    void expand_key(const uint8_t* key, size_t key_len) {
        uint32_t nk = static_cast<uint32_t>(key_len) >> 2;
        uint32_t nr = nk + 6;
        uint32_t* rk = reinterpret_cast<uint32_t*>(ctx_.round_keys);

        for (uint32_t i = 0; i < nk; i++) {
            rk[i] = load_le32(key + 4 * i);
        }

        static const uint8_t rcon[] = {
            0x01, 0x02, 0x04, 0x08, 0x10, 0x20, 0x40, 0x80, 0x1b, 0x36
        };

        for (uint32_t i = nk; i < 4 * (nr + 1); i++) {
            uint32_t temp = rk[i - 1];
            if (i % nk == 0) {
                temp = sub_word(rotr32(temp, 8)) ^ rcon[(i / nk) - 1];
            } else if (nk > 6 && (i % nk) == 4) {
                temp = sub_word(temp);
            }
            rk[i] = rk[i - nk] ^ temp;
        }
    }

    void encrypt_single_block(const uint8_t* in, uint8_t* out) {
        uint32_t s0, s1, s2, s3;
        uint32_t t0, t1, t2, t3;
        const uint32_t* rk = reinterpret_cast<const uint32_t*>(ctx_.round_keys);

        s0 = load_le32(in)      ^ rk[0];
        s1 = load_le32(in + 4)  ^ rk[1];
        s2 = load_le32(in + 8)  ^ rk[2];
        s3 = load_le32(in + 12) ^ rk[3];

        for (uint32_t r = 1; r < ctx_.nr; r++) {
            t0 = te0(s0) ^ te1(s1) ^ te2(s2) ^ te3(s3) ^ rk[4*r];
            t1 = te0(s1) ^ te1(s2) ^ te2(s3) ^ te3(s0) ^ rk[4*r+1];
            t2 = te0(s2) ^ te1(s3) ^ te2(s0) ^ te3(s1) ^ rk[4*r+2];
            t3 = te0(s3) ^ te1(s0) ^ te2(s1) ^ te3(s2) ^ rk[4*r+3];
            s0 = t0; s1 = t1; s2 = t2; s3 = t3;
        }

        store_le32(out,      final_round(s0, s1, s2, s3, 0) ^ rk[4*ctx_.nr]);
        store_le32(out + 4,  final_round(s1, s2, s3, s0, 0) ^ rk[4*ctx_.nr+1]);
        store_le32(out + 8,  final_round(s2, s3, s0, s1, 0) ^ rk[4*ctx_.nr+2]);
        store_le32(out + 12, final_round(s3, s0, s1, s2, 0) ^ rk[4*ctx_.nr+3]);
    }

    static uint32_t sub_word(uint32_t w) {
        return (sbox((w >> 0) & 0xFF)) |
               (sbox((w >> 8) & 0xFF) << 8) |
               (sbox((w >> 16) & 0xFF) << 16) |
               (sbox((w >> 24) & 0xFF) << 24);
    }

    static uint8_t sbox(uint8_t x) {
        static const uint8_t s[256] = {
            0x63,0x7c,0x77,0x7b,0xf2,0x6b,0x6f,0xc5,0x30,0x01,0x67,0x2b,0xfe,0xd7,0xab,0x76,
            0xca,0x82,0xc9,0x7d,0xfa,0x59,0x47,0xf0,0xad,0xd4,0xa2,0xaf,0x9c,0xa4,0x72,0xc0,
            0xb7,0xfd,0x93,0x26,0x36,0x3f,0xf7,0xcc,0x34,0xa5,0xe5,0xf1,0x71,0xd8,0x31,0x15,
            0x04,0xc7,0x23,0xc3,0x18,0x96,0x05,0x9a,0x07,0x12,0x80,0xe2,0xeb,0x27,0xb2,0x75,
            0x09,0x83,0x2c,0x1a,0x1b,0x6e,0x5a,0xa0,0x52,0x3b,0xd6,0xb3,0x29,0xe3,0x2f,0x84,
            0x53,0xd1,0x00,0xed,0x20,0xfc,0xb1,0x5b,0x6a,0xcb,0xbe,0x39,0x4a,0x4c,0x58,0xcf,
            0xd0,0xef,0xaa,0xfb,0x43,0x4d,0x33,0x85,0x45,0xf9,0x02,0x7f,0x50,0x3c,0x9f,0xa8,
            0x51,0xa3,0x40,0x8f,0x92,0x9d,0x38,0xf5,0xbc,0xb6,0xda,0x21,0x10,0xff,0xf3,0xd2,
