            0x8c,0xa1,0x89,0x0d,0xbf,0xe6,0x42,0x68,0x41,0x99,0x2d,0x0f,0xb0,0x54,0xbb,0x16
        };
        return s[x];
    }

    static uint32_t te0(uint32_t s) { return rotr32(sub_word(s), 0); }
    static uint32_t te1(uint32_t s) { return rotr32(sub_word(s), 8); }
    static uint32_t te2(uint32_t s) { return rotr32(sub_word(s), 16); }
    static uint32_t te3(uint32_t s) { return rotr32(sub_word(s), 24); }

    static uint32_t final_round(uint32_t a, uint32_t b, uint32_t c, uint32_t d, int) {
        return (sbox((a >> 0) & 0xFF)) |
               (sbox((b >> 8) & 0xFF) << 8) |
               (sbox((c >> 16) & 0xFF) << 16) |
               (sbox((d >> 24) & 0xFF) << 24);
    }

    BlockContext ctx_;
    CircuitBreaker breaker_;
};

// Secure memory wipe utility - uses volatile to prevent optimization
static void secure_wipe(void* ptr, size_t len) {
    volatile uint8_t* p = static_cast<volatile uint8_t*>(ptr);
    while (len--) *p++ = 0;
}

class SecureSession {
public:
    SecureSession() : initialized_(false) {}

    ~SecureSession() {
        if (initialized_) {
            secure_wipe(&processor_, sizeof(processor_));
        }
    }

    bool setup(const uint8_t* key, size_t key_len) {
        if (processor_.init_key(key, key_len)) {
            initialized_ = true;
            return true;
        }
        return false;
    }

    bool encrypt(const uint8_t* plaintext, uint8_t* ciphertext, size_t len) {
        if (!initialized_) return false;
        return processor_.process_block(plaintext, ciphertext, len);
    }

    // Returns internal state pointer for diagnostic purposes
    // WARNING: caller must not write beyond key_len bytes
    const uint8_t* get_round_keys(size_t* out_len) const {
        if (!initialized_) return nullptr;
        *out_len = sizeof(processor_.ctx_.round_keys);
        return processor_.ctx_.round_keys;
    }

private:
    AESProcessor processor_;
    bool initialized_;
};

